package com.pharmapack.qms.aql; import com.pharmapack.qms.batch.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/aql") public class AqlController { final AqlPlanRepository pr; final AqlInspectionRepository ir; final BatchRepository br; public AqlController(AqlPlanRepository p,AqlInspectionRepository i,BatchRepository b){pr=p;ir=i;br=b;}
 @GetMapping("/plans") public List<AqlPlan> plans(){return pr.findAll();} @GetMapping("/inspections") public List<AqlInspectionResponse> inspections(){return ir.findAllWithRefs().stream().map(this::dto).toList();}
 public record Create(Long batchId,Long planId,Long inspectorId,Integer sampleSize,Integer defectsFound,String remarks){}
 @PostMapping("/inspections") @ResponseStatus(HttpStatus.CREATED) public AqlInspectionResponse create(@RequestBody Create x){AqlPlan p=pr.findById(x.planId()).orElseThrow(()->new IllegalArgumentException("AQL plan not found")); Batch b=br.findById(x.batchId()).orElseThrow(()->new IllegalArgumentException("Batch not found")); int d=x.defectsFound()==null?0:x.defectsFound(); String result=d>=p.getRejectionNumber()?"REJECT":(d<=p.getAcceptanceNumber()?"ACCEPT":"REVIEW"); AqlInspection a=new AqlInspection();a.setBatch(b);a.setAqlPlan(p);a.setInspectorId(x.inspectorId());a.setInspectionTime(LocalDateTime.now());a.setSampleSize(x.sampleSize()==null?p.getSampleSize():x.sampleSize());a.setDefectsFound(d);a.setResult(result);a.setRemarks(x.remarks());AqlInspection saved=ir.save(a);return dto(ir.findById(saved.getId()).orElseThrow());}
 AqlInspectionResponse dto(AqlInspection a){var b=a.getBatch();var p=a.getAqlPlan();return new AqlInspectionResponse(a.getId(),b.getId(),b.getBatchNumber(),b.getProduct().getProductCode(),b.getProduct().getProductName(),p.getId(),p.getPlanCode(),a.getInspectorId(),a.getInspectionTime(),a.getSampleSize(),a.getDefectsFound(),a.getResult(),a.getRemarks());}
}
